WFJ.Data.add("gossip", {
  ["1d072c53bff180c0"] = { "Combatteremo questi demoni, insieme! Anche i Difensori di Nottequieta sono tra noi. Combatteranno fino alla morte, se glielo si chiede. Ora, presto, dobbiamo ricacciare queste aberrazioni nell'Incubo. Distruggetele tutte!", "." },
  ["1d0941a5f6086506"] = { "La mia formazione è ancora in corso, e le tue conoscenze superano le mie. Se vuoi imparare altro, devi parlare con Me'lynn. Ti guiderà lei.", "." },
  ["1d10e862cc5c608e"] = { "Elune sia lodata! Cerchi il nostro maestro di battaglia della ⟦Warsong Gulch=Forra dei Cantaguerra⟧? Si chiama Aethalas, e ti aspetta vicino agli istruttori dei guerrieri.", "." },
  ["1d1541ff3eb1b1e9"] = { "%s si rotola per terra dalle risate.", "." },
  ["1d1800ba52bd789b"] = { "Cosa si fa durante la Veglia delle Ombre?", "." },
  ["1d193ae61ff09348"] = { "Grazie al Capoguerra, perfino qui, tra le rovine della nostra antica prigione, resta un po' di speranza, e l'⟦Horde=Orda⟧ risorge.", "." },
  ["1d255aed4582e1b3"] = { "Non ho tempo per te, {race}. Prosegui per la tua strada.", "." },
  ["1d28a5a2b1e18c7b"] = { "Hai una certa abilità, è vero, ma ogni momento che passo a istruirti è un momento in più di tormento per i non morti. Dimostrami che vali il mio tempo.", "." },
  ["1d2cd656a2090d06"] = { "È giunto il momento, <fratello/sorella> <mio/mia> d'armi, di strappare la notte al Flagello!", "." },
  ["1d31c41deb05414c"] = { "Ehi, Jangdor, puoi insegnarmi di nuovo a fare una ⟦Wild Leather Vest=Veste di Cuoio Selvatico⟧?", "." },
  ["1d422c860c5c5176"] = { "Siediti qui e ascolterai una sto... *hic* una stor... *hic* una storiaaa *hic* Accidenti!", "." },
  ["1d42c0f25df3ed72"] = { "Non può essere! Qui comando io! Voi mortali non siete nulla per quelli come me! Mi sentite? Nulla!", "." },
  ["1d43727a646c56a2"] = { "Gli spiriti hanno guidato i tuoi passi fino a me, e per questo sento su di me la loro benedizione.", "." },
  ["1d4545b60822ce11"] = { "Pulisciti le mani prima di cominciare qualsiasi lavoro. Macchiare il cuoio di sangue o di sporcizia ne guasterebbe la bellezza naturale.", "." },
  ["1d45e0b599aa034d"] = { "Grazie! Grazie, <sacerdote/sacerdotessa>. Ora posso affrontare quegli alberiani corrotti con il potere di Elune al mio fianco!", "." },
  ["1d48f89d05495122"] = { "Smettila di frignare!", "." },
  ["1d4a5b1e03b31f3c"] = { "Sì, sì, tutto il materiale bellico dell'Orda e dell'Alleanza viene spedito a ⟦Silithus=Silitus⟧ e dovrebbe arrivare entro $2113w giorni. Sai cosa succede allora, {class}? Ci sbrighiamo per poi aspettare. Speriamo che qualcuno stia raccogliendo i pezzi dello Scettro delle Sabbie Mutevoli, perché per aprire le porte di ⟦Ahn'Qiraj=Ahn'qiraj⟧ bisogna farlo risuonare contro il gong sull'Altare dello Scarabeo.", "." },
  ["1d5a4dcc2a27b5e0"] = { "Mi hai chiesto di istruirti, e in cambio ho un favore da chiederti. Portalo a termine e avrai la tua ricompensa.", "." },
  ["1d5c6a4e852cb1f0"] = { "Il mio scopo è regolare l'accesso al complesso di Uldum per conto dei Creatori. Consento l'ingresso nel complesso solo quando il richiedente esibisce i dischi di sequenza adeguati.\n\nIl tuo set di dischi al momento non contiene le Plates of Uldum, requisito primario per l'ingresso. L'accesso non è consentito se le Plates of Uldum non sono presenti.", "." },
  ["1d5ccab5d719577b"] = { "Cerchi Zamja al Borstan's Firepit, al livello superiore di The Drag. Sali le scale a sinistra quando entri in The Drag dalla ⟦Valley of Strength=Valle della Forza⟧.", "." },
  ["1d5da07a687d0910"] = { "Dammi il cucciolo di tigre!", "." },
  ["1d68ee6272716010"] = { "Ricorda, ho bisogno del tuo aiuto per incanalare come si deve. Ti chiederò di aiutarmi più volte lungo il cammino, quindi resta all'erta.", "." },
  ["1d6d88812e540c56"] = { "⟦Tower Point=Torre Granguardia⟧ è stata presa dall'⟦Horde=Orda⟧!", "." },
  ["1d7170fdc0fe7d03"] = { "%s cominciano a spintonarsi avanti e indietro.", "." },
  ["1d7662c7123434f1"] = { "Quindi vuoi fare il fabbro, eh? Prendi un grembiule e un martello, <ragazzo/ragazza>, vediamo cosa sai fare.", "." },
  ["1d8262e6b4a0a9cf"] = { "Basta giocare?", "." },
  ["1d89aebebd69b2fc"] = { "Spero che tu sia qui per aiutarci a riprenderci il ⟦Arathi Basin=Bacino d'Arathi⟧ dai ⟦The Defilers=Profanatori⟧. Che ne dici, {name}?", "." },
  ["1d8d69574681c6c7"] = { "Vado a prenderti degli attrezzi, {name}.", "." },
  ["1d93073e4d28d015"] = { "Quali merci della Lega di Arathor ho ormai il diritto di acquistare?", "." },
  ["1da18296ce265106"] = { "Aber? Sei tu...? Oh... ho così fame, Aber! TANTA FAME!!", "." },
  ["1da4910b947eb570"] = { "Sei qui a far visita alla famiglia? Muori, <sciocco/sciocca>!", "." },
  ["1da618a5c391a87e"] = { "Vincono i Rossi! Preparatevi per il prossimo turno.", "." },
  ["1da9a81409129b94"] = { "Grazie ancora per avermi restituito il mio metro portafortuna, {name}. Giuro che mi aiuta a prendere pesci più grossi!", "." },
  ["1daa6e8209f335e3"] = { "Cos'è un ⟦Alliance Commendation Signet=Anello d'Encomio dell'Alleanza⟧?", "." },
  ["1dab1ace44b316de"] = { "Che Elune cammini con te, {class}. Il ⟦Temple of the Moon=Tempio della Luna⟧ è venuto in aiuto dei cittadini in difficoltà di Auberdine.", "." },
  ["1dada2649fa17d21"] = { "Ma come diavolo hai fatto a finire lì dentro?", "." },
  ["1db426a057e33bab"] = { "Sei <tornato/tornata>! Che piacere vederti, {name}. Le mie ferite sono guarite e son quasi pronto a tornare al Lago di Lettofreddo, appena riesco a convincere mia moglie che starò bene.", "." },
  ["1db66fd66aa8bb35"] = { "Parlami della ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧.", "." },
  ["1db731997572844a"] = { "Ah, il vischio...", "." },
  ["1dbffbec18f5165d"] = { "%s riacquista il suo potere e si libera dalle catene!", "." },
  ["1dc14a62130fa887"] = { "Mi manca la birra nanica che bevevamo in quella locanda di Lordaeron. Ti ricordi la rissa che ci abbiamo scatenato?", "." },
  ["1dc51b3e0f1f3e85"] = { "La tua sorte è tracciata, {class}. Per le prossime ore sentirai il tuo spirito in sintonia con la tua vera natura. Fai attenzione, perché la tua sorte, e il tuo destino, non sono mai chiari come potresti pensare.\n\nSe desideri un piccolo scorcio di qualcosa su cui riflettere per il tuo futuro, non hai che da dirmelo. Mi farà piacere darti un responso scritto, purché tu abbia spazio nell'inventario. È tratto dall'intuito che hai mostrato rispondendo alle mie domande.", "." },
  ["1dcd64b5ae728402"] = { "Finalmente avrò la mia vendetta!", "." },
  ["1dd4ae0a97be2fb2"] = { "Cos'era quel rumore? Sembrava un ruggito.", "." },
  ["1dd57f161bc69942"] = { "Non smetterai mai di darmi la caccia, vero? Va bene, ma non mi abbatterai senza combattere!", "." },
  ["1dd5bd420fc3b22d"] = { "Ora lo sento, {name}. ⟦Ashenvale=Valtetra⟧ si trova lungo questo sentiero.", "." },
  ["1de08fdd54d62f1e"] = { "Vengo dalla terra laggiù... dove le donne appestano e gli uomini squarciano.", "." },
  ["1de2dddb582ecc7b"] = { "Che cos'è questo???", "." },
  ["1dfbf58477bed65e"] = { "Salute, {class}. Sono l'ufficiale degli encomi che agisce per conto di ⟦Undercity=Sepulcra⟧. Il mio dovere è assistere gli avventurieri che hanno ricevuto Anelli d'Encomio dell'⟦Horde=Orda⟧.\n\nAccetto anelli in quantità diverse, ma lo scambio più vantaggioso per te è consegnarne un set di dieci in una volta. Quando consegnerai gli anelli, registrerò le tue imprese nei nostri archivi. Di conseguenza, otterrai il riconoscimento di ⟦Undercity=Sepulcra⟧ per il tuo impegno e il tuo servizio.", "." },
})
